using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;
using Sace.Api.Domain;
using Sace.Api.Infrastructure;
using Sace.Api.Services;
using Xunit;

namespace Sace.Api.Tests;

public class AdvancedLegalEngineTests {
  [Fact] public async Task Future_rule_is_ignored_on_2026_12_31(){await using var f=await Fixture.Create(new DateTime(2026,12,31,0,0,0,DateTimeKind.Utc),LegalRuleStatus.VERIFIED,new DateTime(2027,1,1,0,0,0,DateTimeKind.Utc),"YES");var summary=await f.Run();Assert.Equal(0,summary.RulesEvaluated);Assert.Empty(await f.Db.AuditResults.Where(x=>x.AuditId==summary.AuditId).ToListAsync());}
  [Fact] public async Task Future_rule_is_selected_on_effective_date(){await using var f=await Fixture.Create(new DateTime(2027,1,1,0,0,0,DateTimeKind.Utc),LegalRuleStatus.VERIFIED,new DateTime(2027,1,1,0,0,0,DateTimeKind.Utc),"YES");var summary=await f.Run();Assert.Equal(1,summary.RulesEvaluated);Assert.Equal(1,summary.Compliant);}
  [Fact] public async Task Complementary_provision_rule_remains_excluded_on_2027_01_01(){await using var f=await Fixture.Create(new DateTime(2027,1,1,0,0,0,DateTimeKind.Utc),LegalRuleStatus.REVIEW_REQUIRED,new DateTime(2027,1,1,0,0,0,DateTimeKind.Utc),"NO");f.Rule.Code="LEGAL-LA151-VII-PENDING";f.Rule.Limitations="Depende de disposiciones posteriores previstas por el Segundo Transitorio.";await f.Db.SaveChangesAsync();var summary=await f.Run();Assert.Equal(SourceVerificationStatus.VERIFIED,f.Source.Status);Assert.Equal(0,summary.RulesEvaluated);Assert.Empty(await f.Db.Findings.ToListAsync());}
  [Fact] public async Task Draft_rule_is_never_evaluated(){await using var f=await Fixture.Create(new DateTime(2027,2,1,0,0,0,DateTimeKind.Utc),LegalRuleStatus.DRAFT,new DateTime(2027,1,1,0,0,0,DateTimeKind.Utc),"NO");Assert.Equal(0,(await f.Run()).RulesEvaluated);}
  [Fact] public async Task Non_compliant_result_creates_exactly_one_legal_finding(){await using var f=await Fixture.Create(DateTime.UtcNow.Date,LegalRuleStatus.VERIFIED,DateTime.UtcNow.Date.AddDays(-1),"NO");var summary=await f.Run();Assert.Equal(1,summary.NonCompliant);var finding=Assert.Single(await f.Db.Findings.Where(x=>x.AuditId==summary.AuditId).ToListAsync());Assert.Equal(FindingStatus.OPEN,finding.Status);Assert.NotNull(finding.OriginalAuditResultId);}
  [Fact] public async Task Compliant_result_does_not_create_finding(){await using var f=await Fixture.Create(DateTime.UtcNow.Date,LegalRuleStatus.VERIFIED,DateTime.UtcNow.Date.AddDays(-1),"YES");var summary=await f.Run();Assert.Equal(1,summary.Compliant);Assert.Empty(await f.Db.Findings.Where(x=>x.AuditId==summary.AuditId).ToListAsync());}
  [Fact] public async Task Missing_required_evidence_is_insufficient_and_has_no_finding(){await using var f=await Fixture.Create(DateTime.UtcNow.Date,LegalRuleStatus.VERIFIED,DateTime.UtcNow.Date.AddDays(-1),null);var summary=await f.Run();Assert.Equal(1,summary.InsufficientEvidence);Assert.Empty(await f.Db.Findings.Where(x=>x.AuditId==summary.AuditId).ToListAsync());}
  [Fact] public async Task Not_applicable_result_does_not_create_finding(){await using var f=await Fixture.Create(DateTime.UtcNow.Date,LegalRuleStatus.VERIFIED,DateTime.UtcNow.Date.AddDays(-1),"NO");f.Rule.LegalConditions.Single().FailureBehavior=LegalFailureBehavior.NOT_APPLICABLE;await f.Db.SaveChangesAsync();var summary=await f.Run();Assert.Equal(1,summary.NotApplicable);Assert.Empty(await f.Db.Findings.ToListAsync());}
  [Fact] public async Task Manual_review_result_does_not_create_finding_and_records_human_review(){await using var f=await Fixture.Create(DateTime.UtcNow.Date,LegalRuleStatus.VERIFIED,DateTime.UtcNow.Date.AddDays(-1),"YES");f.Rule.LegalEvidenceRequirements.Single().ManualVerificationRequired=true;await f.Db.SaveChangesAsync();var summary=await f.Run();Assert.Equal(1,summary.ManualReview);Assert.Empty(await f.Db.Findings.ToListAsync());var result=await f.Db.AuditResults.SingleAsync(x=>x.AuditId==summary.AuditId);var review=await new LegalReviewService(f.Db).ReviewAsync(result.Id,f.User.Id,LegalReviewDecisionType.CONFIRM,LegalOutcome.COMPLIANT,"Revisión humana documentada.");Assert.Equal(f.User.Id,review.ReviewerUserId);Assert.Equal("Revisión humana documentada.",review.Reason);Assert.NotEqual(default,review.ReviewedAt);Assert.Single(await f.Db.LegalReviewDecisions.ToListAsync());}
  [Fact] public async Task Evaluation_keeps_immutable_rule_source_and_evidence_snapshot(){await using var f=await Fixture.Create(DateTime.UtcNow.Date,LegalRuleStatus.VERIFIED,DateTime.UtcNow.Date.AddDays(-1),"YES");var first=await f.Run();var stored=await f.Db.AuditResults.Include(x=>x.LegalEvidence).SingleAsync(x=>x.AuditId==first.AuditId);var snapshot=stored.SourceCitationSnapshot;var effectiveFrom=stored.RuleEffectiveFrom;f.Rule.Name="Título modificado después";f.Rule.EffectiveFrom=f.Rule.EffectiveFrom.AddYears(-1);f.Source.Title="Fuente modificada después";f.Resolver.Value="MODIFIED";await f.Db.SaveChangesAsync();f.Db.ChangeTracker.Clear();var check=await f.Db.AuditResults.Include(x=>x.LegalEvidence).SingleAsync(x=>x.Id==stored.Id);Assert.Equal("LEGAL-TEST-001",check.RuleCode);Assert.Equal(1,check.RuleVersion);Assert.Equal("Regla de prueba",check.RuleTitle);Assert.Equal(effectiveFrom,check.RuleEffectiveFrom);Assert.Equal(snapshot,check.SourceCitationSnapshot);Assert.Contains("Fuente oficial sint",snapshot);Assert.Contains("EffectiveFrom",snapshot);var evidence=Assert.Single(check.LegalEvidence);Assert.Equal("YES",evidence.RawValue);Assert.Equal("YES",evidence.NormalizedValue);Assert.NotNull(check.Explanation);}
  [Fact] public async Task Reaudit_preserves_non_compliant_result_and_original_finding_then_creates_compliant_result(){await using var f=await Fixture.Create(DateTime.UtcNow.Date,LegalRuleStatus.VERIFIED,DateTime.UtcNow.Date.AddDays(-1),"NO");var first=await f.Run();var original=await f.Db.AuditResults.SingleAsync(x=>x.AuditId==first.AuditId);var finding=await f.Db.Findings.SingleAsync();f.Resolver.Value="YES";var second=await f.Run();f.Db.ChangeTracker.Clear();Assert.NotEqual(first.AuditId,second.AuditId);Assert.Equal(LegalOutcome.NON_COMPLIANT,(await f.Db.AuditResults.SingleAsync(x=>x.Id==original.Id)).Outcome);Assert.Equal(LegalOutcome.COMPLIANT,(await f.Db.AuditResults.SingleAsync(x=>x.AuditId==second.AuditId)).Outcome);Assert.Equal(original.Id,(await f.Db.Findings.SingleAsync(x=>x.Id==finding.Id)).OriginalAuditResultId);Assert.Equal(1,await f.Db.Findings.CountAsync());}
  [Fact] public async Task Human_override_preserves_automatic_outcome_and_dismisses_finding(){await using var f=await Fixture.Create(DateTime.UtcNow.Date,LegalRuleStatus.VERIFIED,DateTime.UtcNow.Date.AddDays(-1),"NO");var run=await f.Run();var result=await f.Db.AuditResults.SingleAsync(x=>x.AuditId==run.AuditId);var service=new LegalReviewService(f.Db);await service.ReviewAsync(result.Id,f.User.Id,LegalReviewDecisionType.OVERRIDE,LegalOutcome.COMPLIANT,"Evidencia humana verificada.");f.Db.ChangeTracker.Clear();var saved=await f.Db.AuditResults.SingleAsync(x=>x.Id==result.Id);var finding=await f.Db.Findings.SingleAsync();Assert.Equal(LegalOutcome.NON_COMPLIANT,saved.Outcome);Assert.Equal(LegalOutcome.COMPLIANT,saved.ManualOutcome);Assert.Equal(FindingStatus.DISMISSED,finding.Status);Assert.Single(await f.Db.LegalReviewDecisions.ToListAsync());}
  [Fact] public async Task Verified_rule_with_unverified_source_is_excluded(){await using var f=await Fixture.Create(DateTime.UtcNow.Date,LegalRuleStatus.VERIFIED,DateTime.UtcNow.Date.AddDays(-1),"NO");f.Source.Status=SourceVerificationStatus.STAGED;await f.Db.SaveChangesAsync();Assert.Equal(0,(await f.Run()).RulesEvaluated);}

  [Theory]
  [InlineData("CROSS_MISMATCH")]
  [InlineData("VALUATION_MISMATCH")]
  [InlineData("CONTRIBUTION_MISMATCH")]
  [InlineData("RRNA_MISSING_EVIDENCE")]
  [InlineData("IMMEX_PAST_DUE")]
  [InlineData("RISK_SCORE_100")]
  public async Task Technical_or_risk_signal_without_complete_verified_rule_never_creates_non_compliance(string signal){await using var f=await Fixture.Create(DateTime.UtcNow.Date,LegalRuleStatus.REVIEW_REQUIRED,DateTime.UtcNow.Date.AddDays(-1),signal);var summary=await f.Run();Assert.Equal(0,summary.NonCompliant);Assert.Empty(await f.Db.Findings.ToListAsync());}

  sealed class StubResolver(string? value):ILegalEvidenceResolver { public string? Value{get;set;}=value;public Task<IReadOnlyList<LegalEvidenceCandidate>> ResolveAsync(TradeOperation operation,NormativeRule rule,CancellationToken ct=default){IReadOnlyList<LegalEvidenceCandidate> rows=Value is null?[]:[new(LegalEvidenceType.TRADE_OPERATION,"FLAG","TradeOperation",operation.Id,"FLAG",Value,Value,null,1,null,null,"Evidencia sintética controlada.")];return Task.FromResult(rows);} }
  sealed class Fixture(SqliteConnection connection,SaceDbContext db,TradeOperation operation,User user,NormativeRule rule,OfficialLegalSource source,StubResolver resolver):IAsyncDisposable {
    public SaceDbContext Db=>db;public User User=>user;public NormativeRule Rule=>rule;public OfficialLegalSource Source=>source;public StubResolver Resolver=>resolver;
    public Task<AdvancedLegalAuditSummary> Run()=>new LegalAuditEngineV2(db,resolver).ExecuteAsync(operation.Id,user.Id);
    public static async Task<Fixture> Create(DateTime operationDate,LegalRuleStatus status,DateTime effectiveFrom,string? evidence){var connection=new SqliteConnection("DataSource=:memory:");await connection.OpenAsync();var db=new SaceDbContext(new DbContextOptionsBuilder<SaceDbContext>().UseSqlite(connection).Options);await db.Database.EnsureCreatedAsync();var user=new User{Name="Legal Tester",Email=$"{Guid.NewGuid():N}@example.invalid",PasswordHash="x"};var other=new DocumentType{Code="OTHER",Name="Otro"};var op=new TradeOperation{Folio=$"LEGAL-{Guid.NewGuid():N}",PedimentoNumber="26 48 TEST",Period=operationDate.ToString("yyyy-MM"),OperationDate=operationDate,TariffFraction="00000000"};var source=new OfficialLegalSource{Code=$"SRC-{Guid.NewGuid():N}",Title="Fuente oficial sintética",SourceType=OfficialSourceType.DOF_PUBLICATION,Authority="Autoridad de prueba",OfficialUrl="https://example.invalid/official",Status=SourceVerificationStatus.VERIFIED};var version=new OfficialLegalSourceVersion{Version=1,VersionLabel="Versión de prueba",PublicationDate=effectiveFrom.AddDays(-10),EffectiveFrom=effectiveFrom,OfficialUrl=source.OfficialUrl,VerificationStatus=SourceVerificationStatus.VERIFIED};var citation=new OfficialSourceCitation{CitationType=OfficialCitationType.ARTICLE,CitationLabel="Artículo de prueba",Article="1",OfficialUrl=source.OfficialUrl};version.Citations.Add(citation);source.Versions.Add(version);var rule=new NormativeRule{Code="LEGAL-TEST-001",Name="Regla de prueba",Description="Regla jurídica sintética para pruebas deterministas.",NormativeSource=NormativeSource.CustomsLaw,RuleCategory=RuleCategory.LEGAL,IsLegalRule=true,IsIncludedInLegalCompliance=true,IsActive=true,LegalStatus=status,Version=1,EffectiveFrom=effectiveFrom,AutomationLevel=AutomationLevel.AUTOMATIC};rule.LegalEvidenceRequirements.Add(new(){Code="FLAG",Name="Bandera",EvidenceType=LegalEvidenceType.TRADE_OPERATION,Required=true});rule.LegalConditions.Add(new(){GroupCode="A",FieldCode="FLAG",Operator=LegalConditionOperator.EQUALS,ExpectedValue="YES",FailureBehavior=LegalFailureBehavior.NON_COMPLIANT});rule.LegalSourceCitations.Add(new(){OfficialSourceCitation=citation,IsPrimary=true});db.AddRange(user,other,op,source,rule);await db.SaveChangesAsync();return new(connection,db,op,user,rule,source,new StubResolver(evidence));}
    public async ValueTask DisposeAsync(){await db.DisposeAsync();await connection.DisposeAsync();}
  }
}
